import fluent.syntax.ast as FTL
from fluent.migratetb.helpers import VARIABLE_REFERENCE, transforms_from
from fluent.migratetb.transforms import REPLACE, PLURALS, REPLACE_IN_TEXT


def migrate(ctx):
    """Bug 1935334 - Migrate cookies from PluralForm.sys.mjs, part {index}."""

    source = "mail/chrome/messenger/preferences/preferences.properties"
    target = reference = "mail/messenger/preferences/cookies.ftl"

    ctx.add_transforms(
        target,
        reference,
        [
            FTL.Message(
                id=FTL.Identifier("remove-selected-cookies"),
                attributes=[
                    FTL.Attribute(
                       id=FTL.Identifier("label"),
                       value=PLURALS(
                          source,
                          "removeSelectedCookies",
                          VARIABLE_REFERENCE("count"),
                          foreach=lambda n: REPLACE_IN_TEXT(
                              n,
                              dict(
                                  {
                                      "#1": VARIABLE_REFERENCE("count"),
                                  }
                              ),
                          ),
                       )
                    ),
                ],
            )
        ]
    )
